/// The grammar callbacks (functions in the highlight.js sources) that have a
/// hand-written twin in callbacks.rs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub(crate) enum Callback {
    /// core.js skipIfHasPrecedingDot: the internal __beforeBegin of every beginKeywords mode
    SkipIfHasPrecedingDot = 1,
    /// hljs.SHEBANG on:begin: only at index 0
    ShebangAtStart = 2,
    /// hljs.END_SAME_AS_BEGIN on:begin: data._beginMatch = m[1]
    SaveBeginMatch = 3,
    /// hljs.END_SAME_AS_BEGIN on:end (php HEREDOC uses the same text): ignore unless m[1] === data._beginMatch
    EndSameAsBegin = 4,
    /// php HEREDOC on:begin: data._beginMatch = m[1] || m[2]
    SaveBeginMatch1Or2 = 5,
    /// javascript / typescript XML_TAG.isTrulyOpeningTag (JSX vs generics look-ahead)
    JsIsTrulyOpeningTag = 6,
}

impl Callback {
    pub(crate) fn from_id(id: u8) -> Option<Callback> {
        Some(match id {
            1 => Callback::SkipIfHasPrecedingDot,
            2 => Callback::ShebangAtStart,
            3 => Callback::SaveBeginMatch,
            4 => Callback::EndSameAsBegin,
            5 => Callback::SaveBeginMatch1Or2,
            6 => Callback::JsIsTrulyOpeningTag,
            _ => return None,
        })
    }
}
